import {
  Mesh,
  PlaneGeometry,
  MeshBasicNodeMaterial,
  TextureLoader,
  ClampToEdgeWrapping,
  Vector3,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // --- Geometry ---
  // Source rect: 512 x 320 -> aspect 1.6
  const aspect = 512 / 320;
  const geometry = new PlaneGeometry(aspect, 1);

  // --- Material (TSL) ---
  const texture = ctx.textureLoader.load(config.imageUrl);
  texture.wrapS = texture.wrapT = ClampToEdgeWrapping;

  // Set UV repeat/offset after texture loads (async but synchronous function can set callback)
  texture.onLoad = () => {
    const img = texture.image;
    const w = img ? img.width : 512;
    const h = img ? img.height : 320;
    texture.repeat.set(512 / w, 320 / h);
    texture.offset.set(0, 0);
    texture.needsUpdate = true;
  };

  const material = new MeshBasicNodeMaterial();
  material.mapNode = texture; // three/tsl node for texture

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.position.set(config.position.x, config.position.y, config.position.z);
  mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  mesh.scale.set(config.scale.x, config.scale.y, config.scale.z);

  // --- Billboard behavior ---
  const up = new Vector3(0, 1, 0);
  mesh.onBeforeRender = function (renderer, scene, camera) {
    this.quaternion.setFromRotationMatrix(
      new THREE.Matrix4().lookAt(this.position, camera.position, up)
    );
    // Preserve original scale (lookAt may affect scale if matrix is applied directly)
    this.scale.set(config.scale.x, config.scale.y, config.scale.z);
  };

  // --- User data ---
  mesh.userData.handlers = {};

  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Remove onBeforeRender reference
    mesh.onBeforeRender = null;
    // Kill any GSAP timelines (none in this node)
  };

  return mesh;
}
